import React, { useState, useEffect } from 'react';
import { GoogleGenerativeAI } from "@google/generative-ai";

const GEMINI_API_KEY = "AIzaSyAycjPVxkbcJFfOSJyTp8oBUsONgK7lY1k"; // Senin Key
const WEATHER_API_KEY = "https://api.openweathermap.org/data/2.5/weather?lat={lat}&lon={lon}&appid={API key}"; 

function App() {
  const [mekanlar, setMekanlar] = useState([]);
  const [favoriler, setFavoriler] = useState([]);
  const [filtreKategori, setFiltreKategori] = useState('Hepsi');
  const [maxSure, setMaxSure] = useState('');

  const [seciliMekan, setSeciliMekan] = useState(null);
  const [aiBilgi, setAiBilgi] = useState({ cevap: "", temp: "", durum: "" });
  const [loading, setLoading] = useState(false);

  // Verileri Çek
  useEffect(() => {
    fetch('http://localhost:5000/api/rota')
      .then(res => res.json())
      .then(data => setMekanlar(data))
      .catch(err => console.error("API Hatası:", err));
  }, []);

  // Hesaplamalar
  const toplamSure = favoriler.reduce((toplam, m) => toplam + (parseInt(m.sure) || 0), 0);
  const toplamButce = favoriler.reduce((toplam, m) => toplam + (parseInt(m.ucret) || 0), 0);
  const saat = Math.floor(toplamSure / 60);
  const dakika = toplamSure % 60;

  // Akıllı AI ve Hava Durumu Fonksiyonu
  const askSmartAI = async (mekan) => {
    setLoading(true);
    setSeciliMekan(mekan);
    setAiBilgi({ cevap: "", temp: "", durum: "" });

    try {
      // 1. Gerçek Zamanlı Hava Durumunu Çek
      const wRes = await fetch(`https://api.openweathermap.org/data/2.5/weather?lat=${mekan.lat}&lon=${mekan.lon}&units=metric&lang=tr&appid=${WEATHER_API_KEY}`);
      const wData = await wRes.json();
      const temp = Math.round(wData.main.temp);
      const desc = wData.weather[0].description;

      // 2. Gemini ile Analiz Et
      const genAI = new GoogleGenerativeAI(GEMINI_API_KEY);
      const model = genAI.getGenerativeModel({ model: "gemini-1.5-flash"});

      const prompt = `Antalya'daki "${mekan.ad}" hakkında hava şu an ${temp} derece ve ${desc}. 
      Buraya gitmek isteyen birine mekanın önemini ve hava durumuna göre (giysi, yanına alınacaklar vb.) samimi bir tavsiye ver. 
      Cevap 2-3 cümle olsun ve Türkçe olsun.`;

      const result = await model.generateContent(prompt);
      const text = await result.response.text();

      setAiBilgi({ cevap: text, temp: temp, durum: desc });

    } catch (error) {
      setAiBilgi(prev => ({ ...prev, cevap: "Hava durumu bilgisi şu an alınamıyor ama burası harika bir yer!" }));
    } finally {
      setLoading(false);
    }
  };

  const toggleFavori = (mekan) => {
    const varMi = favoriler.find(f => f.id === mekan.id);
    if (varMi) {
      setFavoriler(favoriler.filter(f => f.id !== mekan.id));
    } else {
      setFavoriler([...favoriler, mekan]);
    }
  };

  const filtrelenmisMekanlar = mekanlar.filter(m => {
    const katUygun = filtreKategori === 'Hepsi' || m.kategori === filtreKategori;
    const sureUygun = !maxSure || m.sure <= parseInt(maxSure);
    return katUygun && sureUygun;
  });

  return (
    <div className="app-container">
      <link href="https://fonts.googleapis.com/css2?family=Poppins:wght@300;400;500;600;700&display=swap" rel="stylesheet" />

      {/* Stil bloklarını aynen koruyup modal kısmını geliştiriyoruz */}
      <style>{`
        :root { --primary: #0e7490; --accent: #f97316; --bg: #f0f9ff; }
        body { font-family: 'Poppins', sans-serif; background: var(--bg); margin:0; }
        .app-container { max-width: 1200px; margin: 0 auto; padding: 20px; }
        .navbar { display: flex; justify-content: space-between; align-items: center; padding: 20px 0; }
        .brand { font-size: 24px; font-weight: 800; color: var(--primary); }
        .nav-stats { background: white; padding: 10px 20px; border-radius: 50px; display: flex; gap: 20px; box-shadow: 0 4px 10px rgba(0,0,0,0.05); }
        .grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); gap: 25px; margin-top: 30px; }
        .card { background: white; border-radius: 20px; overflow: hidden; box-shadow: 0 10px 20px rgba(0,0,0,0.05); transition: 0.3s; }
        .card:hover { transform: translateY(-5px); }
        .card-img { width: 100%; height: 200px; object-fit: cover; }
        .card-content { padding: 20px; }
        .btn-group { display: flex; gap: 10px; padding: 0 20px 20px; }
        .btn { flex: 1; padding: 12px; border-radius: 10px; border: none; cursor: pointer; font-weight: 600; }
        .btn-ai { background: #ecfeff; color: var(--primary); border: 1px solid #bae6fd; }
        .btn-add { background: var(--primary); color: white; }
        .btn-remove { background: #fef2f2; color: #ef4444; border: 1px solid #fecaca; }
        .modal-overlay { position: fixed; inset: 0; background: rgba(0,0,0,0.5); display: flex; align-items: center; justifyContent: center; z-index: 1000; backdrop-filter: blur(4px); }
        .modal-card { background: white; padding: 30px; border-radius: 25px; max-width: 500px; width: 90%; }
        .ai-badge { display: flex; align-items: center; gap: 10px; background: #f0f9ff; padding: 15px; border-radius: 15px; margin-top: 15px; border: 1px solid #bae6fd; }
      `}</style>

      {/* Navbar & Filters (Aynen Korundu) */}
      <nav className="navbar">
        <div className="brand">🧭 ROTA<span>ASİSTANI</span></div>
        <div className="nav-stats">
            <span>⏱ {saat}s {dakika}d</span>
            <span>💰 {toplamButce} ₺</span>
        </div>
      </nav>

      {/* Grid */}
      <div className="grid">
        {filtrelenmisMekanlar.map(mekan => (
          <div key={mekan.id} className="card">
            <img src={mekan.resim} className="card-img" alt={mekan.ad} />
            <div className="card-content">
              <h3 style={{margin:0}}>{mekan.ad}</h3>
              <p style={{fontSize:'13px', color:'#64748b'}}>{mekan.aciklama}</p>
              <div style={{display:'flex', justifyContent:'space-between', marginTop:15, fontSize:'13px', fontWeight:600}}>
                <span>📍 {mekan.bolge}</span>
                <span style={{color:'var(--primary)'}}>{mekan.ucret === 0 ? "Ücretsiz" : `${mekan.ucret} ₺`}</span>
              </div>
            </div>
            <div className="btn-group">
              <button className="btn btn-ai" onClick={() => askSmartAI(mekan)}>✨ Akıllı Bilgi</button>
              <button className={`btn ${favoriler.some(f => f.id === mekan.id) ? 'btn-remove' : 'btn-add'}`} onClick={() => toggleFavori(mekan)}>
                {favoriler.some(f => f.id === mekan.id) ? 'Çıkar' : 'Ekle +'}
              </button>
            </div>
          </div>
        ))}
      </div>

      {/* AKILLI MODAL */}
      {seciliMekan && (
        <div className="modal-overlay" onClick={() => setSeciliMekan(null)}>
          <div className="modal-card" onClick={e => e.stopPropagation()}>
            <h2 style={{color:'var(--primary)', marginTop:0}}>{seciliMekan.ad}</h2>
            <p>{seciliMekan.aciklama}</p>

            <div className="ai-badge">
              <div style={{fontSize:'30px'}}>{loading ? "⚙️" : "🌤️"}</div>
              <div>
                <div style={{fontWeight:700, color:'#0369a1'}}>
                   {loading ? "Veriler analiz ediliyor..." : `${aiBilgi.temp}°C - ${aiBilgi.durum.toUpperCase()}`}
                </div>
                <div style={{fontSize:'14px', marginTop:5, fontStyle:'italic'}}>
                  {loading ? "Yapay zeka hava durumuna göre tavsiye oluşturuyor..." : `"${aiBilgi.cevap}"`}
                </div>
              </div>
            </div>

            <button className="btn btn-add" style={{marginTop:20, width:'100%'}} onClick={() => setSeciliMekan(null)}>Anladım, Kapat</button>
          </div>
        </div>
      )}
    </div>
  );
}

export default App;
